const usuario = $('Identificar Usuario').first().json;
const webhook = $('Webhook').first().json;
const aiItem = $input.first().json;

let parsed;

try {
    // 1. Pega a string que está dentro da chave 'output'
    let rawText = aiItem.output || '';

    // Se por acaso vier de outra forma, tenta o objeto completo
    if (!rawText && typeof aiItem === 'string') {
        rawText = aiItem;
    }

    // 2. Limpa qualquer resquício de Markdown ou quebra de linha que a OpenAI possa colocar
    let cleanText = String(rawText)
        .replace(/```json/gi, '')
        .replace(/```/g, '')
        .trim();

    // 3. Captura o que está entre as chaves { ... }
    const match = cleanText.match(/\{[\s\S]*\}/);
    let jsonString = match ? match[0] : cleanText;

    // 4. Transforma a string em um objeto JavaScript real
    parsed = JSON.parse(jsonString);

} catch (e) {
    // Fallback de segurança caso o JSON venha corrompido
    parsed = { 
        intencao: 'outro', 
        entidades: {}, 
        resposta_sugerida: 'Não foi possível processar o formato da resposta da IA.' 
    };
}

// Mapeamento seguro da mensagem vinda do webhook do WhatsApp
let mensagemOriginal = '';
if (webhook.body?.data?.message) {
    const m = webhook.body.data.message;
    mensagemOriginal = m.conversation || m.extendedTextMessage?.text || m.text || '';
}

// Normaliza a intencao contra o enum valido, corrigindo erros comuns da IA
const INTENCOES_VALIDAS = ['registrar_parto','registrar_leite','registrar_cobertura',
    'consultar_vaca','consultar_relatorio','cadastrar_vaca','atualizar_registro','atualizar_vaca','deletar_registro','diagnosticar_prenhez',
    'registrar_financeiro','consultar_financeiro','atualizar_financeiro','deletar_financeiro'];
const ALIASES_INTENCAO = {
    'consult_vaca': 'consultar_vaca',
    'consultar_relatório': 'consultar_relatorio',
    'registrar_cobertura ': 'registrar_cobertura'
};
function normalizarIntencao(raw) {
    if (!raw) return 'outro';
    let v = String(raw).trim().toLowerCase();
    if (INTENCOES_VALIDAS.includes(v)) return v;
    if (ALIASES_INTENCAO[v]) return ALIASES_INTENCAO[v];
    // tenta achar a intencao valida mais proxima por prefixo/substring (nunca cai em registrar_* ou deletar_* por seguranca)
    const candidata = INTENCOES_VALIDAS.find(i => i.startsWith(v) || v.startsWith(i));
    if (candidata && !candidata.startsWith('deletar')) return candidata;
    return 'outro';
}

// 5. Retorno limpo e estruturado para o seu banco/Supabase
return [{
    json: {
        intencao: normalizarIntencao(parsed.intencao),
        entidades: {
            numero_vaca: parsed.entidades?.numero_vaca ?? null,
            data: parsed.entidades?.data ?? null,
            litros: parsed.entidades?.litros ?? null,
            periodo: parsed.entidades?.periodo ?? null,
            sexo_bezerro: parsed.entidades?.sexo_bezerro ?? null,
            touro_semen: parsed.entidades?.touro_semen ?? null,
            observacao: parsed.entidades?.observacao ?? null,
            tipo_relatorio: parsed.entidades?.tipo_relatorio ?? null,
            periodo_dias: parsed.entidades?.periodo_dias ?? null,
            resultado_diagnostico: parsed.entidades?.resultado_diagnostico ?? null,
            numero_mae: parsed.entidades?.numero_mae ?? null,
            status_produtivo: parsed.entidades?.status_produtivo ?? null,
            status_reprodutivo: parsed.entidades?.status_reprodutivo ?? null,
            tipo_financeiro: parsed.entidades?.tipo_financeiro ?? null,
            categoria: parsed.entidades?.categoria ?? null,
            valor: parsed.entidades?.valor ?? null
        },
        resposta_sugerida: parsed.resposta_sugerida || '',
        propriedade_id: usuario?.propriedade_id || null,
        telefone: usuario?.telefone || null,
        mensagem_original: mensagemOriginal || 'vaca 10 produziu 12 litros'
    }
}];

const anterior = $input.first().json.data || '';
const atual = $('Preparar Dados Buffer').first().json.mensagemAtual;
const novoBuffer = anterior ? (anterior + '\n' + atual) : atual;
return [{ json: { novoBuffer } }];

const dedupeById = (arr) => { const seen = new Set(); return arr.filter(x => { if (!x || !x.id || seen.has(x.id)) return false; seen.add(x.id); return true; }); };
const vaca = $('Buscar Vaca (Relatório)').first().json;
let registros = dedupeById($input.all().map(i => i.json));
registros.sort((a, b) => new Date(b.data_controle) - new Date(a.data_controle));
registros = registros.slice(0, 10);
let texto = `Relatório da vaca ${vaca.numero_identificacao}:\n`;
if (registros.length === 0) {
  texto += 'Nenhum registro de leite encontrado.';
} else {
  const total = registros.reduce((s, r) => s + (Number(r.litros) || 0), 0);
  texto += registros.map(r => `- ${r.data_controle}: ${r.litros}L`).join('\n');
  texto += `\nTotal no período consultado: ${total}L`;
}
return [{ json: { resposta_sugerida: texto } }];

const dedupeById = (arr) => { const seen = new Set(); return arr.filter(x => { if (!x || !x.id || seen.has(x.id)) return false; seen.add(x.id); return true; }); };
const { periodoDias, label, dataInicio } = $('Calcular Período Geral').item.json;

const hoje = new Date();
const hojeStr = hoje.toISOString().slice(0, 10);

let registros = dedupeById($input.all().map(i => i.json));
registros = registros.filter(r => r.data_controle >= dataInicio && r.data_controle <= hojeStr);

let texto;
if (registros.length === 0) {
  texto = `Nenhum registro de leite encontrado (${label}).`;
} else {
  const total = registros.reduce((s, r) => s + (Number(r.litros) || 0), 0);
  if (periodoDias > 0) {
    const porDia = {};
    for (const r of registros) {
      porDia[r.data_controle] = (porDia[r.data_controle] || 0) + (Number(r.litros) || 0);
    }
    const dias = Object.keys(porDia).sort();
    texto = `Produção (${label}): ${total}L em ${registros.length} lançamento(s).\n\n`;
    texto += dias.map(d => `- ${d}: ${porDia[d]}L`).join('\n');
  } else {
    texto = `Produção de hoje: ${total}L em ${registros.length} lançamento(s).`;
  }
}
return [{ json: { resposta_sugerida: texto } }];

const registro = $input.first().json;
const vaca = $('Buscar Vaca (Deletar)').first().json;
const telefone = $('Parsear Resposta IA').first().json.telefone;
const pendencia = {
  tipo: 'leite',
  registro_id: registro.id,
  numero_vaca: vaca.numero_identificacao,
  data_controle: registro.data_controle,
  periodo: registro.periodo,
  litros: registro.litros
};
const texto = `Confirma excluir o registro da vaca ${vaca.numero_identificacao} (${registro.data_controle}, ${registro.periodo}, ${registro.litros}L)? Responda SIM para confirmar ou NAO para cancelar.`;
return [{ json: { telefone, pendencia: JSON.stringify(pendencia), resposta_sugerida: texto } }];

const msg = (String($('Preparar Entrada Agente').first().json.mensagem_compilada || '')).toLowerCase();
const pendencia = JSON.parse($input.first().json.data);
const telefone = $('Preparar Entrada Agente').first().json.telefone;
const confirmado = /\b(sim|confirma|confirmar|pode)\b/.test(msg);
const cancelado = /\b(nao|não|cancela|cancelar)\b/.test(msg);
return [{ json: { telefone, pendencia, confirmado: confirmado && !cancelado } }];

const dedupeById = (arr) => { const seen = new Set(); return arr.filter(x => { if (!x || !x.id || seen.has(x.id)) return false; seen.add(x.id); return true; }); };
const coberturas = dedupeById($('Buscar Cobertura Recente (Parto)').all().map(i => i.json));
let coberturaId = null;
if (coberturas.length > 0) {
  coberturas.sort((a, b) => new Date(b.data_cobertura) - new Date(a.data_cobertura));
  coberturaId = coberturas[0].id;
}

let iep = null;
let partoAnterior = null;
try { partoAnterior = $('Buscar Parto Anterior (Ativo)').first().json; } catch (e) {}
if (partoAnterior && partoAnterior.data_parto) {
  const dataPartoNovo = $('Parsear Resposta IA').item.json.entidades.data || new Date().toISOString().slice(0, 10);
  const dNovo = new Date(dataPartoNovo);
  const dAnterior = new Date(partoAnterior.data_parto);
  iep = Math.round((dNovo - dAnterior) / 86400000);
}

return [{ json: { cobertura_id: coberturaId, iep } }];

const dedupeById = (arr) => { const seen = new Set(); return arr.filter(x => { if (!x || !x.id || seen.has(x.id)) return false; seen.add(x.id); return true; }); };
const vaca = $('Buscar Vaca (Reprodutivo Individual)').first().json;
let parto = null;
try { parto = $('Buscar Parto Ativo (Reprodutivo)').first().json; } catch (e) {}
const coberturas = dedupeById($('Buscar Coberturas (Reprodutivo Individual)').all().map(i => i.json));
coberturas.sort((a, b) => new Date(b.data_cobertura) - new Date(a.data_cobertura));
const ultima = coberturas[0] || null;

const hoje = new Date();
const diffDias = (a, b) => Math.round((new Date(a) - new Date(b)) / 86400000);

let texto = `Status reprodutivo da vaca ${vaca.numero_identificacao}:\n`;
texto += `Status reprodutivo cadastrado: ${vaca.status_reprodutivo || 'não informado'}\n`;

if (parto && parto.id) {
  texto += `Lactação ativa desde ${parto.data_parto}.\n`;
  if (parto.iep != null) texto += `IEP: ${parto.iep} dias. `;

  const coberturasPosParto = coberturas
    .filter(c => new Date(c.data_cobertura) >= new Date(parto.data_parto))
    .sort((a, b) => new Date(a.data_cobertura) - new Date(b.data_cobertura));
  const coberturaConfirmada = coberturasPosParto.find(c => c.diagnostico_prenhez === 'positivo');
  const diasEmAberto = coberturaConfirmada
    ? diffDias(coberturaConfirmada.data_cobertura, parto.data_parto)
    : diffDias(hoje, parto.data_parto);
  texto += `Dias em aberto: ${diasEmAberto}. `;

  const registrosLeite = dedupeById($('Buscar Controle Leite Ativo (Reprodutivo)').all().map(i => i.json));
  const diasEmLactacao = Math.max(1, diffDias(hoje, parto.data_parto));
  if (registrosLeite.length > 0) {
    const totalLitros = registrosLeite.reduce((s, r) => s + (Number(r.litros) || 0), 0);
    const projecao305 = Math.round((totalLitros / diasEmLactacao) * 305);
    texto += `Projeção 305d: ${projecao305}L. `;

    if (diasEmLactacao >= 60) {
      const dataLimite1 = new Date(hoje); dataLimite1.setDate(dataLimite1.getDate() - 30);
      const dataLimite2 = new Date(hoje); dataLimite2.setDate(dataLimite2.getDate() - 60);
      const str1 = dataLimite1.toISOString().slice(0, 10);
      const str2 = dataLimite2.toISOString().slice(0, 10);
      const hojeStr = hoje.toISOString().slice(0, 10);
      const janela1 = registrosLeite.filter(r => r.data_controle > str1 && r.data_controle <= hojeStr);
      const janela2 = registrosLeite.filter(r => r.data_controle > str2 && r.data_controle <= str1);
      const media1 = janela1.reduce((s, r) => s + (Number(r.litros) || 0), 0) / 30;
      const media2 = janela2.reduce((s, r) => s + (Number(r.litros) || 0), 0) / 30;
      if (media2 > 0) {
        const persistencia = Math.round((media1 / media2) * 1000) / 10;
        texto += `Persistência: ${persistencia}%. `;
      }
    }
  }
  texto += `\n`;
} else {
  texto += `Sem lactação ativa registrada.\n`;
}

if (ultima) {
  texto += `Última cobertura: ${ultima.data_cobertura} (diagnóstico: ${ultima.diagnostico_prenhez}).\n`;
  if (ultima.diagnostico_prenhez === 'positivo') {
    const dCob = new Date(ultima.data_cobertura);
    const dParto = new Date(dCob.getTime() + 283 * 86400000);
    const dSeca = new Date(dParto.getTime() - 60 * 86400000);
    texto += `Previsão de parto: ${dParto.toISOString().slice(0,10)}. `;
    texto += `Previsão de secagem: ${dSeca.toISOString().slice(0,10)}.\n`;
  }
} else {
  texto += `Nenhuma cobertura registrada.\n`;
}

return [{ json: { resposta_sugerida: texto } }];

const dedupeById = (arr) => { const seen = new Set(); return arr.filter(x => { if (!x || !x.id || seen.has(x.id)) return false; seen.add(x.id); return true; }); };
const vacas = dedupeById($('Buscar Vacas Propriedade (Reprodutivo)').all().map(i => i.json));
const vacaIds = new Set(vacas.map(v => v.id));
const numeroPorId = Object.fromEntries(vacas.map(v => [v.id, v.numero_identificacao]));

const todasCoberturas = dedupeById($('Buscar Coberturas (Reprodutivo Geral)').all().map(i => i.json))
  .filter(c => vacaIds.has(c.vaca_id));
const todosPartos = dedupeById($('Buscar Partos (Reprodutivo Geral)').all().map(i => i.json))
  .filter(p => vacaIds.has(p.vaca_id));
const todoControleLeite = dedupeById($('Buscar Controle Leite (Reprodutivo Geral)').all().map(i => i.json));

const coberturaIdsComParto = new Set(todosPartos.filter(p => p.cobertura_id).map(p => p.cobertura_id));

const pendentes = todasCoberturas.filter(c => c.diagnostico_prenhez === 'pendente');
const positivasSemParto = todasCoberturas.filter(c => c.diagnostico_prenhez === 'positivo' && !coberturaIdsComParto.has(c.id));

const previsoes = positivasSemParto.map(c => {
  const dCob = new Date(c.data_cobertura);
  const dParto = new Date(dCob.getTime() + 283 * 86400000);
  const dSeca = new Date(dParto.getTime() - 60 * 86400000);
  return {
    numero: numeroPorId[c.vaca_id] || '?',
    dataParto: dParto.toISOString().slice(0,10),
    dataSeca: dSeca.toISOString().slice(0,10)
  };
}).sort((a, b) => new Date(a.dataParto) - new Date(b.dataParto));

const partosAtivos = todosPartos.filter(p => p.ativa);

const hoje = new Date();
const diffDias = (a, b) => Math.round((new Date(a) - new Date(b)) / 86400000);

const leitePorParto = {};
for (const r of todoControleLeite) {
  if (!leitePorParto[r.parto_id]) leitePorParto[r.parto_id] = [];
  leitePorParto[r.parto_id].push(r);
}

const indicadores = partosAtivos.map(p => {
  const registros = leitePorParto[p.id] || [];
  const diasEmLactacao = Math.max(1, diffDias(hoje, p.data_parto));

  const coberturasVaca = todasCoberturas.filter(c => c.vaca_id === p.vaca_id);
  const coberturasPosParto = coberturasVaca
    .filter(c => new Date(c.data_cobertura) >= new Date(p.data_parto))
    .sort((a, b) => new Date(a.data_cobertura) - new Date(b.data_cobertura));
  const coberturaConfirmada = coberturasPosParto.find(c => c.diagnostico_prenhez === 'positivo');
  const diasEmAberto = coberturaConfirmada
    ? diffDias(coberturaConfirmada.data_cobertura, p.data_parto)
    : diffDias(hoje, p.data_parto);

  let projecao305 = null;
  let persistencia = null;
  if (registros.length > 0) {
    const totalLitros = registros.reduce((s, r) => s + (Number(r.litros) || 0), 0);
    projecao305 = Math.round((totalLitros / diasEmLactacao) * 305);

    if (diasEmLactacao >= 60) {
      const dataLimite1 = new Date(hoje); dataLimite1.setDate(dataLimite1.getDate() - 30);
      const dataLimite2 = new Date(hoje); dataLimite2.setDate(dataLimite2.getDate() - 60);
      const str1 = dataLimite1.toISOString().slice(0, 10);
      const str2 = dataLimite2.toISOString().slice(0, 10);
      const hojeStr = hoje.toISOString().slice(0, 10);
      const janela1 = registros.filter(r => r.data_controle > str1 && r.data_controle <= hojeStr);
      const janela2 = registros.filter(r => r.data_controle > str2 && r.data_controle <= str1);
      const media1 = janela1.reduce((s, r) => s + (Number(r.litros) || 0), 0) / 30;
      const media2 = janela2.reduce((s, r) => s + (Number(r.litros) || 0), 0) / 30;
      if (media2 > 0) persistencia = Math.round((media1 / media2) * 1000) / 10;
    }
  }

  return {
    numero: numeroPorId[p.vaca_id] || '?',
    iep: p.iep,
    diasEmAberto,
    persistencia,
    projecao305
  };
});

let texto = 'Relatório reprodutivo do rebanho:\n\n';

texto += `Previsão de parto (${previsoes.length}):\n`;
texto += previsoes.length
  ? previsoes.map(p => `- Vaca ${p.numero}: parto em ${p.dataParto}`).join('\n')
  : 'Nenhuma prevista.';
texto += '\n\n';

texto += 'Vacas para secar (próximos 30 dias):\n';
const secarProximas = previsoes.filter(p => {
  const d = new Date(p.dataSeca);
  const diff = (d - hoje) / 86400000;
  return diff >= -5 && diff <= 30;
});
texto += secarProximas.length
  ? secarProximas.map(p => `- Vaca ${p.numero}: secar até ${p.dataSeca}`).join('\n')
  : 'Nenhuma vaca para secar no período.';
texto += '\n\n';

texto += `Coberturas com diagnóstico pendente (${pendentes.length}):\n`;
texto += pendentes.length
  ? pendentes.map(c => `- Vaca ${numeroPorId[c.vaca_id] || '?'}: cobertura em ${c.data_cobertura}`).join('\n')
  : 'Nenhuma pendência.';
texto += '\n\n';

texto += `Indicadores das lactações ativas (${indicadores.length}):\n`;
texto += indicadores.length
  ? indicadores.map(p => {
      const partes = [`Vaca ${p.numero}`];
      if (p.iep != null) partes.push(`IEP ${p.iep}d`);
      partes.push(`dias em aberto ${p.diasEmAberto}`);
      if (p.persistencia != null) partes.push(`persistência ${p.persistencia}%`);
      if (p.projecao305 != null) partes.push(`proj. 305d ${p.projecao305}L`);
      return '- ' + partes.join(', ');
    }).join('\n')
  : 'Nenhuma lactação ativa.';

return [{ json: { resposta_sugerida: texto } }];

const dedupeById = (arr) => { const seen = new Set(); return arr.filter(x => { if (!x || !x.id || seen.has(x.id)) return false; seen.add(x.id); return true; }); };
const vacas = dedupeById($input.all().map(i => i.json));

const porStatusProdutivo = {};
const porStatusReprodutivo = {};
for (const v of vacas) {
  const sp = v.status_produtivo || 'não informado';
  const sr = v.status_reprodutivo || 'não informado';
  porStatusProdutivo[sp] = (porStatusProdutivo[sp] || 0) + 1;
  porStatusReprodutivo[sr] = (porStatusReprodutivo[sr] || 0) + 1;
}

let texto = `Total de vacas cadastradas: ${vacas.length}\n\n`;
texto += 'Por status produtivo:\n';
texto += Object.entries(porStatusProdutivo).map(([k, v]) => `- ${k}: ${v}`).join('\n');
texto += '\n\nPor status reprodutivo:\n';
texto += Object.entries(porStatusReprodutivo).map(([k, v]) => `- ${k}: ${v}`).join('\n');

return [{ json: { resposta_sugerida: texto } }];

const msg = $('Webhook').item.json.body.data.message;
const base64 = (msg.audioMessage && msg.audioMessage.base64) || msg.base64 || null;
if (!base64) {
  throw new Error('Audio recebido mas nenhum campo base64 foi encontrado no payload. Verifique a estrutura real do webhook de audio da Evolution API (body.data.message) e ajuste este node.');
}
return [{
  json: {},
  binary: {
    audio: { data: base64, mimeType: 'audio/ogg', fileName: 'audio.ogg' }
  }
}];

const parsed = $('Parsear Resposta IA').item.json;
const periodoDiasClassificador = parsed.entidades.periodo_dias;
const mensagem = (parsed.mensagem_original || '').toLowerCase();

const hoje = new Date();
let inicio, label, periodoDias;

if (periodoDiasClassificador && periodoDiasClassificador > 0) {
  // classificador deu um numero especifico de dias (ex: "ultimos 3 dias")
  periodoDias = periodoDiasClassificador;
  inicio = new Date(hoje);
  inicio.setDate(inicio.getDate() - periodoDias);
  label = `últimos ${periodoDias} dias`;
} else if (/\bhoje\b/.test(mensagem)) {
  // pediu especificamente "hoje"
  periodoDias = 0;
  inicio = new Date(hoje);
  label = 'hoje';
} else {
  // padrao para relatorio geral sem periodo especifico: mes atual + mes passado
  inicio = new Date(hoje.getFullYear(), hoje.getMonth() - 1, 1);
  const diffMs = hoje - inicio;
  periodoDias = Math.ceil(diffMs / 86400000);
  label = 'mês atual e mês passado';
}

const dataInicio = inicio.toISOString().slice(0, 10);
return [{ json: { dataInicio, periodoDias, label } }];

const vaca = $('Buscar Vaca (Leite)').first().json;
const registro = $input.first().json; // saída do Inserir Controle Leite

const texto = `Registrado ${registro.litros}L da vaca ${vaca.numero_identificacao} em ${registro.data_controle}.`;

return [{ json: { resposta_sugerida: texto } }];

const dedupeById = (arr) => { const seen = new Set(); return arr.filter(x => { if (!x || !x.id || seen.has(x.id)) return false; seen.add(x.id); return true; }); };
const entidades = $('Parsear Resposta IA').item.json.entidades;
let maeId = null;
let bezerroId = null;

if (entidades.numero_mae) {
  try {
    const maeItem = $('Buscar Vaca Mãe (Cadastro)').first();
    const mae = maeItem ? maeItem.json : null;
    if (mae && mae.id) {
      maeId = mae.id;
      let bezerros = [];
      try { bezerros = dedupeById($('Buscar Bezerros da Mãe (Cadastro)').all().map(i => i.json)); } catch (e) {}
      const naoVinculados = bezerros.filter(b => !b.vaca_id_gerada);
      naoVinculados.sort((a, b) => new Date(b.created_at) - new Date(a.created_at));
      if (naoVinculados.length > 0) bezerroId = naoVinculados[0].id;
    }
  } catch (e) {}
}

return [{ json: { maeId, bezerroId } }];

const entidades = $('Parsear Resposta IA').item.json.entidades;
let numeroVaca = entidades.numero_vaca;
let autoGerado = false;

if (!numeroVaca) {
  let vacas = [];
